<template><div class="live-trend"><svg viewBox="0 0 650 260" role="img" aria-label="有效训练次数与参与人数组合图"><text x="10" y="18">次数</text><text x="600" y="18">人数</text><g v-for="i in [0,1,2,3,4]" :key="i"><path :d="`M42 ${220-i*45}H600`" stroke="#edf1ed"/><text x="8" :y="224-i*45">{{Math.round(max*i/4)}}</text><text x="610" :y="224-i*45">{{Math.round(popMax*i/4)}}</text></g><g v-for="(p,i) in points" :key="p.date" tabindex="0" role="button" :aria-label="`${p.date} ${p.count}次 ${p.active}人，查看记录`" @click="$emit('select',p)" @keydown.enter="$emit('select',p)" @keydown.space.prevent="$emit('select',p)"><rect :x="x(i)-bar/2" :y="220-p.count/max*180" :width="bar" :height="p.count/max*180" fill="#a3d5b8" rx="3"/><text :x="x(i)" :y="210-p.count/max*180" text-anchor="middle">{{p.count}}</text><text v-if="i%step===0||i===points.length-1" :x="x(i)" y="250" text-anchor="middle">{{p.date.slice(5)}}</text></g><polyline :points="points.map((p,i)=>`${x(i)},${220-p.active/popMax*180}`).join(' ')" stroke="#78929f" stroke-width="2" fill="none"/><circle v-for="(p,i) in points" :key="p.date" :cx="x(i)" :cy="220-p.active/popMax*180" r="3" fill="#78929f"/></svg><p>柱：有效提交次数（左轴） · 线：参与人数（右轴）</p><details><summary>查看每周数据与不完整周期</summary><div class="la-scroll"><table><thead><tr><th>周期</th><th>次数</th><th>参与人数 / 当前成员</th><th>依据</th></tr></thead><tbody><tr v-for="p in points" :key="p.date"><td>{{p.date}}～{{p.to}}<small v-if="p.partial">未满周</small></td><td>{{p.count}}</td><td>{{p.active}} / {{population}}</td><td><button @click="$emit('select',p)">核查记录</button></td></tr></tbody></table></div></details></div></template>
<script setup>
import {computed} from 'vue'
const props=defineProps({points:{type:Array,default:()=>[]},population:Number});defineEmits(['select'])
const max=computed(()=>Math.ceil(Math.max(4,...props.points.map(p=>p.count))/4)*4),popMax=computed(()=>Math.ceil(Math.max(4,props.population||0)/4)*4),bar=computed(()=>Math.min(40,540/Math.max(1,props.points.length)*.6)),step=computed(()=>Math.max(1,Math.ceil(props.points.length/5))),x=i=>55+(540/Math.max(1,props.points.length))*(i+.5)
</script>
